// src/components/seal/ProvenanceLine.tsx
//
// ProvenanceLine — the second half of the VerificationSeal. Renders the
// model attribution + the review-action attribution (per docs/DESIGN.md
// §7.1).
//
// For pending state: "AI-generated by muse-spark-1.3, not verified" +
//   a chip showing the model_id (or "demo-mock-v1" if isDemo).
// For resolved states: "{action} by {name}, {time}" — e.g.
//   "Confirmed by Maya R., 14:02".
//
// The label text comes from src/lib/design/copy.ts (the canonical copy
// store) — it is NOT overridable by props. This is the safety guarantee
// from the design thesis: "AI observations are always labeled until a
// reviewer acts."

import { type VerificationState } from "@/lib/design/status";
import { COPY, fill } from "@/lib/design/copy";
import { formatAbsoluteTime } from "@/lib/design/format";

export interface ProvenanceLineProps {
  state: VerificationState;
  /** The model id (e.g. "muse-spark-1.3" for live Meta inference,
   *  "demo-mock-v1" for seeded demo data). */
  modelName?: string;
  /** If true, render the demo-mock-v1 chip in brick wash so mock
   *  observations are never mistaken for live Meta inference. */
  isDemo?: boolean;
  /** The reviewer's display name (for resolved states). */
  reviewerName?: string | null;
  /** The review action timestamp (ISO or Date). */
  at?: string | Date | null;
}

const ACTION_VERB: Record<Exclude<VerificationState, "pending" | "failed">, string> = {
  confirmed: "Confirmed",
  corrected: "Corrected",
  flagged: "Flagged for second review",
  rejected: "Rejected",
};

export function ProvenanceLine({
  state,
  modelName = "muse-spark-1.3",
  isDemo = false,
  reviewerName,
  at,
}: ProvenanceLineProps) {
  if (state === "pending") {
    return (
      <div className="provenance">
        <span>{fill(COPY.provenance.pending, { model: modelName })}</span>
        <span className={`provenance__model${isDemo ? " provenance__model--demo" : ""}`}>
          {isDemo ? COPY.provenance.demoChip : modelName}
        </span>
      </div>
    );
  }
  if (state === "failed") {
    return <div className="provenance"><span>{COPY.seal.failed}</span></div>;
  }
  // Resolved state
  const verb = ACTION_VERB[state];
  const name = reviewerName ?? "a reviewer";
  const time = at ? formatAbsoluteTime(at) : "just now";
  return (
    <div className="provenance">
      <span>{fill(COPY.provenance.resolved, { action: verb, name, time })}</span>
    </div>
  );
}
